for q,L in LABELS.items():
    txt=open(W+q+'.txt',encoding='utf-8').read()
    parts=re.split(r'\n### ([0-9A-F]{10}) \|[^\n]*\n', '\n'+txt)
    content={parts[i]:parts[i+1] for i in range(1,len(parts),2)}
    codes=[x[0] for x in L]
    assert len(codes)==len(set(codes)) and set(codes)==set(content), (q,len(codes),len(content),set(codes)^set(content))
    bad=[c for c,g,r,s,cf in L if (g!=0 and not (s and s in content[c])) or (g==0 and s)]
    if bad: print(q,'BAD',bad); continue
    with open(R+q+'.jsonl','w',encoding='utf-8') as f:
        for c,g,r,s,cf in L:
            f.write(json.dumps({"annotation_code":c,"grade":g,"rationale":r,"evidence_span":s,"confidence":cf,"needs_review":False,"review_note":""},ensure_ascii=False)+'\n')
    print(q,'written',len(L))
